class Solution {
public:
    int subarraysWithKDistinct(vector<int>& nums, int k) {
        auto atMost = [&](int distinct) -> int {
            if (distinct <= 0) return 0;
            unordered_map<int, int> count;
            int left = 0;
            int res = 0;
            for (int right = 0; right < (int)nums.size(); ++right) {
                count[nums[right]]++;
                while ((int)count.size() > distinct) {
                    if (--count[nums[left]] == 0) {
                        count.erase(nums[left]);
                    }
                    left++;
                }
                res += right - left + 1;
            }
            return res;
        };
        return atMost(k) - atMost(k - 1);
    }
};

class Solution {
    public int subarraysWithKDistinct(int[] nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);
    }

    private int atMost(int[] nums, int distinct) {
        if (distinct <= 0) return 0;
        Map<Integer, Integer> count = new HashMap<>();
        int left = 0;
        int res = 0;
        for (int right = 0; right < nums.length; ++right) {
            count.put(nums[right], count.getOrDefault(nums[right], 0) + 1);
            while (count.size() > distinct) {
                int leftVal = nums[left];
                count.put(leftVal, count.get(leftVal) - 1);
                if (count.get(leftVal) == 0) {
                    count.remove(leftVal);
                }
                left++;
            }
            res += right - left + 1;
        }
        return res;
    }
}

var subarraysWithKDistinct = function(nums, k) {
    const atMost = function(distinct) {
        if (distinct <= 0) return 0;
        const count = new Map();
        let left = 0;
        let res = 0;
        for (let right = 0; right < nums.length; right++) {
            count.set(nums[right], (count.get(nums[right]) || 0) + 1);
            while (count.size > distinct) {
                const leftVal = nums[left];
                const c = count.get(leftVal) - 1;
                if (c === 0) count.delete(leftVal);
                else count.set(leftVal, c);
                left++;
            }
            res += right - left + 1;
        }
        return res;
    };
    return atMost(k) - atMost(k - 1);
};
